var e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Uma verificação rápida e somente leitura de que a impressora está pronta para iniciar uma impressão.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Verificar novamente`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Verificando...`}},ready:{t:0,b:{t:2,i:[{t:3}],s:`Pronta para imprimir`}},notReady:{t:0,b:{t:2,i:[{t:3}],s:`Não está pronta para imprimir`}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:`A impressora está inacessível`}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:`O Klipper está pronto`}},fail:{t:0,b:{t:2,i:[{t:3,v:`O Klipper não está pronto (estado: `},{t:4,k:`state`},{t:3,v:`)`}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Nenhuma impressão em andamento`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Já há uma impressão em execução (`},{t:4,k:`state`},{t:3,v:`)`}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Todos os eixos estão referenciados`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Eixos não referenciados (`},{t:4,k:`axes`},{t:3,v:`); o início de uma impressão normalmente faz o referenciamento primeiro`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guia`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guia da verificação pré-impressão`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Fechar`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`O que é a verificação pré-impressão?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Uma olhada somente leitura para saber se a impressora está pronta para começar: ela nunca move nem altera nada, apenas informa. Bloqueios críticos deixam o veredito vermelho; avisos informam, mas não bloqueiam.`}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:`O que ela verifica`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Se o Klipper está pronto (sem desligamento ou erro), se nenhuma impressão já está em execução e se os eixos estão referenciados (informativo, já que o início de uma impressão normalmente faz o referenciamento primeiro).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossário`}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:`Estado do Klipper`}},def:{t:0,b:{t:2,i:[{t:3}],s:`O status do próprio Klipper - 'ready' (pronto) significa que está conectado e ocioso; 'shutdown' (desligado) ou 'error' (erro) significa que ele não pode imprimir até que a condição seja resolvida.`}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:`Referenciamento (homing)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Mover cada eixo até seu endstop para que a impressora saiba onde está a toolhead. A maioria das rotinas de início de impressão faz o referenciamento automaticamente.`}}}}}}};export{e as default};